"""``rasa tools init docs`` — fetch offline Rasa documentation files."""

import argparse
import os
import sys
import urllib.request
from pathlib import Path
from typing import Optional

import questionary
from rich.console import Console
from rich.panel import Panel

from rasa.cli.tools.constants import (
    DEFAULT_LLMS_TXT_BASE_URL,
    DEFAULT_MANTLE_LLMS_TXT_BASE_URL,
    ENGINE_MANTLE,
    HTTP_TIMEOUT,
    LLMS_TXT_BASE_URL_ENV_VAR,
    LLMS_TXT_FILES,
    MANTLE_DOCS_SUBDIR,
    MANTLE_LLMS_TXT_BASE_URL_ENV_VAR,
    TOOLS_CONFIG_DIR,
)
from rasa.cli.tools.utils import _precheck, _resolve_project_dir, restore_blocking_io

console = Console()


# Entrypoint ===========================================================================


def docs_tools(args: argparse.Namespace) -> None:
    """Entrypoint for `rasa tools init docs`.

    Args:
        args: The CLI arguments.  An `engine` of `"mantle"` fetches the Mantle
            bundle; anything else (including an omitted engine) keeps the
            historical CALM behaviour.
    """
    _precheck()

    project_dir = _resolve_project_dir(
        getattr(args, "project_path", None), validate_exists=True
    )
    non_interactive = getattr(args, "yes", False)

    if getattr(args, "engine", None) == ENGINE_MANTLE:
        fetch_mantle_docs(project_dir, non_interactive=non_interactive)
        return

    fetch_offline_docs(project_dir, non_interactive=non_interactive)


# Docs fetching & management ===========================================================


def resolve_llms_txt_base_url() -> str:
    """Return the base URL for fetching llms.txt documentation files.

    Reads from the ``RASA_LLMS_TXT_BASE_URL`` environment variable if set,
    otherwise falls back to the default Rasa documentation URL.

    Returns:
        Base URL string (without trailing slash).
    """
    url = os.getenv(LLMS_TXT_BASE_URL_ENV_VAR, DEFAULT_LLMS_TXT_BASE_URL)
    return url.rstrip("/")


def resolve_mantle_llms_txt_base_url() -> str:
    """Return the base URL for fetching the Mantle llms.txt documentation files.

    Reads from the ``RASA_MANTLE_LLMS_TXT_BASE_URL`` environment variable if set,
    otherwise falls back to the default Mantle documentation site.  Kept separate
    from `resolve_llms_txt_base_url` so a CALM docs mirror configured via
    ``RASA_LLMS_TXT_BASE_URL`` cannot redirect Mantle fetches.

    Returns:
        Base URL string (without trailing slash).
    """
    url = os.getenv(MANTLE_LLMS_TXT_BASE_URL_ENV_VAR, DEFAULT_MANTLE_LLMS_TXT_BASE_URL)
    return url.rstrip("/")


def fetch_offline_docs(
    project_dir: Path,
    non_interactive: bool = False,
    *,
    base_url: Optional[str] = None,
    dest_dir: Optional[Path] = None,
) -> None:
    """Download the offline docs bundle (llms.txt files) into the config directory.

    Fetches each file listed in `LLMS_TXT_FILES` from `base_url` and saves them
    under `dest_dir`.  Failures are reported but do not abort the process.

    Args:
        project_dir: Absolute path to the Rasa project root.
        non_interactive: When `True`, skip confirmation prompts and overwrite
            existing docs silently.
        base_url: Base URL to fetch from.  Defaults to the CALM docs URL.
        dest_dir: Directory to write into.  Defaults to `<project_dir>/.rasa/`.

    Keyword-only by design: the CALM callers pass neither, so their behaviour is
    unchanged and no positional argument can drift into them.
    """
    base_url = base_url or resolve_llms_txt_base_url()
    dest_dir = dest_dir or (project_dir / TOOLS_CONFIG_DIR)
    dest_dir.mkdir(parents=True, exist_ok=True)

    existing = [f for f in LLMS_TXT_FILES if (dest_dir / f).exists()]
    if existing and not non_interactive:
        if not _confirm_overwrite_docs(existing, dest_dir):
            console.print("  Skipping docs download.")
            return

    console.print()
    for filename in LLMS_TXT_FILES:
        url = f"{base_url}/{filename}"
        dest = dest_dir / filename
        console.print(f"  Fetching {filename}…", end=" ")
        try:
            with urllib.request.urlopen(url, timeout=HTTP_TIMEOUT) as response:
                dest.write_bytes(response.read())
            console.print("[green]✔[/green]")
            console.print(f"  Saved to [bold]{dest}[/bold]")
        except Exception as exc:
            console.print("[red]✖[/red]")
            console.print(
                f"  [yellow]Could not fetch {filename}:[/yellow] {exc}\n"
                f"  Download manually from [link]{url}[/link]\n"
                f"  and place it at {dest}"
            )


def fetch_mantle_docs(project_dir: Path, non_interactive: bool = False) -> None:
    """Download the Mantle docs bundle for local coding-agent lookup.

    Writes to `<project_dir>/.rasa/docs/mantle/` so it cannot collide with the
    CALM bundle that `rasa tools init` places in `<project_dir>/.rasa/` for a
    CALM project.

    Args:
        project_dir: Absolute path to the Rasa project root.
        non_interactive: When `True`, skip confirmation prompts and overwrite
            existing docs silently.
    """
    fetch_offline_docs(
        project_dir,
        non_interactive=non_interactive,
        base_url=resolve_mantle_llms_txt_base_url(),
        dest_dir=project_dir / TOOLS_CONFIG_DIR / MANTLE_DOCS_SUBDIR,
    )


def _confirm_overwrite_docs(existing: list, dest_dir: Path) -> bool:
    """Ask the user whether to overwrite existing offline docs.

    Args:
        existing: Filenames that already exist on disk.
        dest_dir: Directory where the files live.

    Returns:
        `True` if the user confirms, `False` otherwise.
    """
    file_list = "\n".join(f"  • {dest_dir / f}" for f in existing)
    console.print()
    console.print(
        Panel(
            "[yellow]⚠[/yellow]  [bold]Offline docs already downloaded[/bold]\n\n"
            "The following files already exist:\n\n"
            f"{file_list}\n\n"
            "Continuing will overwrite them with the latest versions.",
            border_style="yellow",
            expand=False,
        )
    )
    answer = questionary.confirm("Overwrite existing docs?", default=False).ask()
    restore_blocking_io()
    if answer is None:
        sys.exit(1)
    return answer
